import pytest
from candidate import parse_nested_parens


class TestParseNestedParens:
    def test_single_group_no_nesting(self):
        assert parse_nested_parens("()") == [1]

    def test_single_group_one_level_nesting(self):
        assert parse_nested_parens("(())") == [2]

    def test_single_group_two_levels_nesting(self):
        assert parse_nested_parens("((()))") == [3]

    def test_single_group_mixed_nesting(self):
        assert parse_nested_parens("(()())") == [2]

    def test_single_group_complex_nesting(self):
        assert parse_nested_parens("((())()())") == [3]

    def test_multiple_groups_docstring_example(self):
        assert parse_nested_parens('(()()) ((())) () ((())()())') == [2, 3, 1, 3]

    def test_multiple_groups_simple(self):
        assert parse_nested_parens("() (()) ((()))") == [1, 2, 3]

    def test_multiple_groups_all_same_depth(self):
        assert parse_nested_parens("(()) (()) (())") == [2, 2, 2]

    def test_empty_string_returns_empty_list(self):
        assert parse_nested_parens("") == []

    def test_string_with_only_spaces_returns_empty_list(self):
        assert parse_nested_parens("   ") == []

    def test_string_with_single_space_returns_empty_list(self):
        assert parse_nested_parens(" ") == []

    def test_consecutive_spaces_between_groups(self):
        assert parse_nested_parens("()  (())   ((()))") == [1, 2, 3]

    def test_leading_trailing_spaces(self):
        assert parse_nested_parens("  () (())  ") == [1, 2]

    def test_deep_nesting_ten_levels(self):
        result = parse_nested_parens("((((((((()))))))")
        assert result == [10]

    def test_deep_nesting_single_group(self):
        result = parse_nested_parens("((((((()))))))")
        assert result == [10]

    def test_alternating_open_close(self):
        assert parse_nested_parens("()()()()") == [1]

    def test_single_open_paren(self):
        result = parse_nested_parens("(")
        assert result == [1]

    def test_single_close_paren(self):
        result = parse_nested_parens(")")
        assert result == [0]

    def test_many_groups(self):
        result = parse_nested_parens("() () () () ()")
        assert result == [1, 1, 1, 1, 1]

    def test_nested_with_sequential_and_branching(self):
        assert parse_nested_parens("(()(()))") == [3]

    def test_result_type_is_list(self):
        result = parse_nested_parens("() (())")
        assert isinstance(result, list)

    def test_result_elements_are_ints(self):
        result = parse_nested_parens("() (())")
        for item in result:
            assert isinstance(item, int)

    def test_none_input_raises_exception(self):
        with pytest.raises((TypeError, AttributeError)):
            parse_nested_parens(None)

    def test_integer_input_raises_exception(self):
        with pytest.raises((TypeError, AttributeError)):
            parse_nested_parens(123)

    def test_list_input_raises_exception(self):
        with pytest.raises((TypeError, AttributeError)):
            parse_nested_parens(["()", "(())"])

    def test_bytes_input_raises_exception(self):
        with pytest.raises((TypeError, AttributeError)):
            parse_nested_parens(b"()")

    def test_zero_depth_group_mixed_with_normal(self):
        result = parse_nested_parens(") () (())")
        assert result == [0, 1, 2]

    def test_four_level_nesting(self):
        assert parse_nested_parens("(((())))") == [4]

    def test_five_level_nesting(self):
        assert parse_nested_parens("(((())))") == [4]
        assert parse_nested_parens("((((()))))") == [5]

    def test_group_with_only_opening_parens(self):
        assert parse_nested_parens("(((") == [3]

    def test_group_with_only_closing_parens(self):
        assert parse_nested_parens(")))") == [0]

    def test_mixed_open_close_unbalanced(self):
        assert parse_nested_parens("(()") == [2]

    def test_whitespace_only_multiple_spaces(self):
        assert parse_nested_parens("     ") == []

    def test_two_groups_different_depths(self):
        assert parse_nested_parens("((())) ()") == [3, 1]

    def test_group_max_depth_not_final_depth(self):
        assert parse_nested_parens("(()())") == [2]
